import"./chunk-2NFLSA4Y.js";var a={orbits:{theory:{concept:"[[An orbit is the path along which a body moves under the gravity of another, more massive body; a satellite in orbit is in free fall.]] A satellite keeps falling towards the planet, but it moves sideways so fast that the surface curves away beneath it."},section:{cannon:{title:"Newton's cannon",text:"Newton imagined a cannon on a very high mountain. A slow cannonball lands nearby. A faster one lands farther away. Because the planet is round, the ground curves away beneath the ball. If it is fast enough, the ground curves away exactly as fast as the ball falls \u2014 and the ball goes all the way round. That is an orbit."},circular:{title:"First cosmic speed: a circle",text:"[[For a circular orbit, gravity must provide exactly the pull needed to keep turning: v\u2081 = \u221A(G\xB7M / r).]] Near the Earth's surface this is about 7.9 km/s; 400 km up, where the International Space Station flies, about 7.7 km/s, and one orbit takes about 92 minutes. The farther from the planet, the slower the circular speed and the longer the orbit."},ellipse:{title:"Faster: an ellipse",text:"Launched faster than v\u2081 but slower than v\u2082, the satellite climbs away, slows down, turns and falls back towards the planet \u2014 along an ellipse with the planet's centre at one focus. It is fastest at the lowest point and slowest at the highest. Slower than v\u2081, the ellipse would dip inside the planet, so the projectile hits the ground."},escape:{title:"Second cosmic speed: escape",text:"Gravity weakens with distance, so a fast enough projectile never comes back. [[The escape velocity is v\u2082 = \u221A(2\xB7G\xB7M / r) = \u221A2 \xB7 v\u2081: about 11.2 km/s from the Earth's surface.]] Exactly at v\u2082 the path is a parabola; faster, a hyperbola. The direction does not matter, only the speed (unless the path hits the planet)."},planets:{title:"Small and big worlds",text:"The escape velocity depends on the planet's mass and size. From the Moon it is only 2.4 km/s, which is why the Apollo astronauts could leave it with a small rocket. From Mars it is 5.0 km/s, and from Jupiter about 60 km/s."},satellites:{title:"Satellites we use",text:"The International Space Station orbits 400 km up. GPS satellites fly about 20 200 km up and go round twice a day. Weather and TV satellites 35 786 km up take exactly one day per orbit, so they stay above the same spot on the equator: a geostationary orbit."},check:{title:"Check your understanding",text:"What happens to a ball launched horizontally at 90 % of v\u2081? (It falls back.) How much faster than v\u2081 must it go to escape? (\u221A2 \u2248 1.41 times.) Why is a high orbit slower and longer? Is the escape velocity from the Moon bigger or smaller than from the Earth? Try each answer in the simulation."}},formula:{circular:"First cosmic speed: circular orbit at distance r from the centre",escape:"Second cosmic speed (escape velocity)",gravity:"Newton's law of universal gravitation",kepler:"Kepler's third law: period of an orbit with semi-major axis a",energy:"Energy per kilogram stays constant: below zero bound, zero or more escapes"},variable:{G:"Gravitational constant, 6.674 \xD7 10\u207B\xB9\xB9 N\xB7m\xB2/kg\xB2",M:"Mass of the planet",r:"Distance from the planet's centre",v:"Speed",a:"Semi-major axis of the ellipse (half its longest width)"},assumption:{planet:"The planet is a perfect sphere that does not rotate or move; only its gravity acts.",noAir:"There is no air resistance \u2014 real launches must also push through the atmosphere.",time:"Simulated time runs much faster than the animation (see the time speed-up).",scale:"The satellite and the arrows are drawn far larger than scale."},param:{planet:"Planet",speed:"Launch speed (% of circular speed)",altitude:"Launch height",angle:"Launch angle",timeScale:"Time speed-up \xD7"},hint:{speed:"100 % is the first cosmic speed (a circle). \u221A2 \u2248 141.4 % is the escape velocity.",altitude:"The height of Newton's imaginary mountain above the surface.",angle:"0\xB0 is horizontal. Positive aims upwards, negative downwards.",timeScale:"How many seconds of flight pass in one second of animation."},preset:{earth:"Earth",moon:"Moon",mars:"Mars",jupiter:"Jupiter",falls:"Falls back",circle:"Circle",ellipse:"Ellipse",escape:"Escape",iss:"Space station",gps:"GPS",geo:"Geostationary"},measure:{flightTime:"Flight time",altitude:"Height above the surface",launchSpeed:"Launch speed",circularSpeed:"First cosmic speed (circle)",escapeSpeed:"Second cosmic speed (escape)",gravity:"Gravity at this height",period:"Time for one orbit",eccentricity:"Eccentricity (0 = circle)",periapsis:"Lowest height of the orbit",apoapsis:"Highest height of the orbit"},view:{falling:"Too slow: it will fall back",crashed:"It hit the ground",circle:"Circular orbit",ellipse:"Elliptical orbit",escaping:"Fast enough to escape",escaped:"Escaped: it will never come back",farAway:"A very long ellipse: it will come back, but much later",circleOption:"Circular orbit for comparison",predictionOption:"Predicted path"},graph:{altitude:"Height against time",speed:"Speed against time"},challenge:{circle:{title:"A perfect circle",description:"Put the satellite into a circular orbit and let it go once round.",hint:"Launch horizontally at exactly 100 % of the circular speed."},escape:{title:"Leave the Earth",description:"Launch from the Earth so fast that it never comes back.",hint:"You need at least \u221A2 \u2248 141.4 % of the circular speed."},farSide:{title:"To the other side",description:"Make the cannonball land at least halfway round the planet.",hint:"It must be almost fast enough for an orbit \u2014 try 90\u201399 %."},moonEscape:{title:"Leaving the Moon",description:"Escape from the Moon. Compare the speed with the Earth's escape velocity.",hint:"Choose the Moon and launch above the escape speed. Look at v\u2082 in km/s."},iss:{title:"Like the space station",description:"Put a satellite into an Earth orbit that takes about 92 minutes.",hint:"The ISS flies in a circle about 400 km up."},geo:{title:"Geostationary",description:"Find the circular orbit that takes exactly one sidereal day (23.93 h).",hint:"Try about 35 800 km. Speed up time so you don't have to wait too long."}}}},i={sim:a};export{i as default,a as sim};
